import sys
lines = sys.stdin.read().splitlines()
out = []
in_stk, out_stk = [], []
def transfer():
    if not out_stk:
        while in_stk: out_stk.append(in_stk.pop())
if lines:
    m = int(lines[0])
    for line in lines[1:1+m]:
        cmd = line.split()
        if not cmd: continue
        if cmd[0] == 'PUSH': in_stk.append(int(cmd[1]))
        elif cmd[0] == 'POP': transfer(); out.append(str(out_stk.pop()))
        elif cmd[0] == 'PEEK': transfer(); out.append(str(out_stk[-1]))
        elif cmd[0] == 'EMPTY': out.append('true' if not in_stk and not out_stk else 'false')
print(' '.join(out))
